create or replace TABLE LDL_PRODUCTION_CLONE_GOOGLE_20260608_1030.P_LEW_CORE.T_BUILDING_HIST cluster by (CLIENT_ID)(
	CLIENT_ID NUMBER(38,0) NOT NULL COMMENT 'unique identifier of the DWH client / slice',
	BUILDING_SID NUMBER(38,0) NOT NULL COMMENT 'Surrogate Key of the building;',
	ADDR_SID NUMBER(38,0) COMMENT 'Associated (main) address of the building',
	BUILDING_STATUS_ID NUMBER(38,0) COMMENT 'building status describing the lifecycle; from building initialized via approved to under contract and open; but also building rejected or finally closed; IMS_ESB object.info.current-status',
	BUILDING_STATUS_DT DATE COMMENT 'Date when the building status has changed; IMS_ESB: object.status-development.status.date; IMS_ESB: object.status_development.status.date0',
	PRECONTRACT_DT DATE COMMENT 'Pre contract date; IMS_ESB: object.status-development.status.status-date.status-date-type = pre-contract: Vorvertragsdatum',
	CONTRACT_DT DATE COMMENT 'Contract date; IMS_ESB: object.status-development.status.status-date.status-date-type = contract: Vertragsdatum',
	CONSTRUCTION_START_DT DATE COMMENT 'Construction start date; IMS_ESB: object.status-development.status.status-date.status-date-type = construction: Baubeginn',
	PLANNED_OPENING_DT DATE COMMENT 'Planned Opening date; IMS_ESB: object.status-development.status.status-date.status-date-type = neo: NEO - Datum - Voraussichtlich\n            \n            ',
	OPENING_DT DATE COMMENT 'Opening date; IMS_ESB: object.status-development.status.status-date.status-date-type = actual-neo: NEO - Datum',
	PLANNED_CLOSING_DT DATE COMMENT 'Planned Closing date; IMS_ESB: object.status-development.status.status-date.status-date-type = plan-closing: Schlie?ung - Datum - Voraussichtlich',
	CLOSING_DT DATE COMMENT 'Closing date; IMS_ESB: object.status-development.status.status-date.status-date-type = closing: Schlie?ung - Datum',
	CLOSING_REASON_ID NUMBER(38,0) COMMENT 'Closing reason code; IMS_ESB object.status_development.status.status_date.closing_reason_id: Schlie?ungsgrund ( If there is more closing_reason_id, only get the  LAST  closing_reason_id )',
	CLOSING_REASON_TXT VARCHAR(1000) COMMENT 'Free text comment on closing; IMS_ESB: object.status_development.status.status_date.remark',
	FINAL_COMPLETION_DT DATE COMMENT 'date of final completion; IMS_ESB: object.status-development.status.status-date.status-date-type = final-completion: Endabwicklung (Datum)',
	CANCELING_DT DATE COMMENT 'date of canceling ; IMS_ESB: object.status-development.status.status-date.status-date-type = cancellation: Stornodatum (Keine Realisierungsabsicht)',
	CANCELING_REASON_ID NUMBER(38,0) COMMENT 'Reason of cancelation; IMS_ESB: object.status_development.status.status_date.cancellation_reason_id.cancellation_reasonType: Stornogrund',
	TEMP_CLOSING_FG NUMBER(38,0) DEFAULT 0 COMMENT 'indicating, whether the building will is temporary closed; IMS_ESB: object.status-development.status.temp-closing.: Vorubergehend geschlossen (Ja / Nein)',
	RECONSTRUCTION_FG NUMBER(38,0) DEFAULT 0 COMMENT 'indicating, whether the building will be demolished and rebuilt; IMS_ESB: object.warehouse-data.demolition',
	PURCHASE_TYPE_ID NUMBER(38,0) COMMENT 'indicating, whether the building is rent (1), bought (2) or leased (3); IMS_ESB: object.info.object-type-id',
	OWNERSHIP_TYPE_ID NUMBER(38,0) COMMENT 'indicating, whether the building is fully owned (0), partially owned (1); IMS_ESB: object.warehouse-data.owner-type',
	LEASING_FG NUMBER(38,0) DEFAULT 0 COMMENT 'indicating, whether the building is leased; IMS_ESB: object.warehouse-data.pt-leasing',
	OWN_ACQUISITION_FG NUMBER(38,0) DEFAULT 0 COMMENT 'indicating, whether the building is own acquisioned; IMS_ESB: object.warehouse-data.own-akquisition',
	CURR_SID NUMBER(38,0) COMMENT 'currency associated with the monetary amounts, e.g. lease_val',
	CURR_CD VARCHAR(3) COLLATE 'en-ci' COMMENT 'currency associated with the monetary amounts, e.g. lease_val: IMS_ESB: object.info.currency',
	LEASE_PER_YEAR_VAL NUMBER(18,5) COMMENT 'yearly cost for renting/leasing; IMS_ESB: object.misc.sum-lease-offer',
	LEASE_INCOME_PER_YEAR_VAL NUMBER(18,5) COMMENT 'yearly income due to leasing; IMS_ESB: object.misc.sum-lease-income',
	SALES_AREA_IN_MEAS NUMBER(18,5) COMMENT 'sales area; IMS_ESB: object.area-data.areas.area (kind=\""bl\"" type=\""1\"")',
	UNIT VARCHAR(4) COLLATE 'en-ci' COMMENT 'unit for sales area; IMS_ESB: object.info.unit',
	PARKING_PLACE_CNT NUMBER(38,0) COMMENT 'total number of parking places: IMS_ESB: object.area-data.parking.total',
	OWNED_PARKING_PLACE_CNT NUMBER(38,0) COMMENT 'total number of owned parking places; IMS_ESB:object.area-data.parking.own',
	GARAGE_PARKING_PLACE_CNT NUMBER(38,0) COMMENT 'total number of garage parking places; IMS_ESB:object.area-data.parking.garage',
	DELETED_FG NUMBER(38,0) NOT NULL COMMENT 'attribute set was not delivered by source system (anymore), if deleted_fg=1',
	DWH_VALID_FROM DATE NOT NULL COMMENT 'Gueltigkeitsbeginn; Teil der DWH-Historisierung; aeltester Satz der Historie erhaelt immer den Wert 01.01.1900 (\""minus unendlich\"")',
	DWH_VALID_TO DATE NOT NULL COMMENT 'Gueltigkeitsende; Teil der DWH-Historisierung; neuster Satz der Historie erhaelt immer den Wert 30.12.9999 (\""plus unendlich\"")',
	DWH_LOAD_ID NUMBER(38,0) NOT NULL COMMENT 'Identifier des letzten Ladelaufs, der den Datensatz eingfuegt oder veraendert hat',
	DWH_CREATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der Ersteinfuegung des Datensatzes ins DWH',
	DWH_UPDATED TIMESTAMP_NTZ(9) NOT NULL COMMENT 'Zeitstempel der letzten Aenderung des Datensatzes im DWH',
	constraint PK_T_BUILDING_HIST primary key (BUILDING_SID, DWH_VALID_FROM)
)COMMENT='$Revision: 0000 $. Physical Buildings like Stores and Warehouses (historicized attributes)'
;
